                  "type": "primary",
                  "operation": "average",
                  "field": "bytes"
                }
              ]
            }
          },
          {
            "grid": {
              "x": 24,
              "y": 5,
              "w": 24,
              "h": 10
            },
            "type": "vis",
            "config": {
              "type": "xy",
              "title": "Requests over time",
